package ru.oopssre.gremlinamp;
public class Regression {
 static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Check "+checks);}
 public static void main(String[] args){PlaybackIdentity identity=new PlaybackIdentity();identity.begin(1,"DK theme","Donkey Kong");check(identity.artwork(1,"dk.png"));identity.begin(2,"Contra theme","Contra");check(identity.snapshot().art.isEmpty());check(!identity.artwork(1,"dk-late.png"));check(identity.snapshot().game.equals("Contra"));check(identity.artwork(2,"contra.png"));check(identity.snapshot().title.equals("Contra theme"));identity.begin(3,"Next","Another game");check(identity.snapshot().art.isEmpty());check(identity.artwork(3,""));check(identity.snapshot().art.isEmpty());check(PlaybackRules.total(14000,5000)==19000);check(PlaybackRules.position(20000,19000,true)==19000);check(PlaybackRules.position(20000,0,false)==20000);check(PlaybackRules.include(-1,10000,"show"));check(!PlaybackRules.include(-1,10000,"hide"));check(PlaybackRules.include(-1,10000,"only"));check(!PlaybackRules.include(700,10000,"show"));check(PlaybackRules.include(10000,10000,"show"));check(!PlaybackRules.include(20000,0,"only"));java.util.Set<String> action=java.util.Set.of("action");check(ContinuationRules.score("series",true,action,action,true)>0);check(ContinuationRules.score("series",false,action,action,true)==0);check(ContinuationRules.score("genre",false,action,action,false)>0);check(ContinuationRules.score("genre",true,action,java.util.Set.of("rpg"),true)==0);check(ContinuationRules.score("similar",true,action,action,true)>ContinuationRules.score("similar",false,action,action,true));check(ContinuationRules.score("similar",false,java.util.Set.of(),java.util.Set.of(),true)==0);check(ContinuationRules.score("stop",true,action,action,true)==0);
for(int size=1;size<=15;size++){java.util.Set<Integer> visited=new java.util.HashSet<>();int pos=0;visited.add(pos);java.util.Random random=new java.util.Random(size);for(int k=1;k<size;k++){int next=ContinuationRules.nextIndex(pos,size,visited,true,false,random);check(next>=0&&next<size&&!visited.contains(next));visited.add(next);pos=next;}check(ContinuationRules.nextIndex(pos,size,visited,true,false,random)==-1);check(ContinuationRules.nextIndex(size-1,size,visited,false,true,random)==0);}
check(ContinuationRules.nextIndex(0,0,new java.util.HashSet<>(),false,false,new java.util.Random())==-1);
long morning=java.time.Instant.parse("2026-11-01T04:00:00Z").toEpochMilli();check(SyncRules.untilMorning(morning-1)==1);check(SyncRules.untilMorning(morning)==86400000);check(SyncRules.untilMorning(morning+1000)==86399000);
System.out.println(checks+" regression checks passed: playback identity, duration filters, continuation, shuffle and scheduling");}
}
